exports.declaration:
interface FrameProbe {
    beginDraw(gl: WebGL2RenderingContext): void;
    endDraw(): void;
    sample(time: number, mainThreadMs: number, intervalMs: number, painted: boolean): void;
}

interface GraphData<N extends GraphNode = GraphNode, E extends GraphLink = GraphLink> {
    nodes: readonly N[];
    links: readonly E[];
}

interface GraphEvents {
    select: string | null;
    /** A click or tap on a node or its label, including repeated clicks on the current selection. */
    nodeclick: string;
    hover: string | null;
    open: string;
    /** A clean click on empty graph space, in canvas CSS pixels. Nodes and labels take precedence. */
    backgroundclick: {
        x: number;
        y: number;
        clicks: number;
    };
    modechange: Mode;
    destroy: undefined;
}

interface GraphFrame {
    /** Changes when the graph rebuilds its projected coordinates. Older frame providers may omit it. */
    readonly projectionVersion?: number;
    /** Four floats per node: screen x, screen y, visible radius, camera depth. */
    readonly points: Readonly<Float32Array>;
    readonly width: number;
    readonly height: number;
    readonly mode: Mode;
    readonly zoom: number;
    readonly yaw: number;
    readonly pitch: number;
    /** Screen coordinate of world zero on the lane axis. */
    readonly laneOrigin: number;
    readonly vertical: boolean;
    /** Lane identifiers and their world-space offsets, in visual order. */
    readonly lanes: ReadonlyMap<string, number>;
}

interface GraphLink {
    /** Optional stable document identity. The editor assigns IDs to older anonymous links. */
    id?: string;
    source: string;
    target: string;
    kind?: string;
    weight?: number;
    metrics?: Readonly<Record<string, number>>;
}

interface GraphNode {
    id: string;
    label?: string;
    kind?: string;
    /** Authored overrides for this marker, applied after theme and taxonomy styling. */
    markerColor?: string;
    markerShape?: NodeShape;
    x?: number;
    y?: number;
    z?: number;
    /** Defaults to true for nodes supplied with both x and y. Set false to seed a movable node. */
    pinned?: boolean;
    art?: string;
    degree?: number;
    section?: string;
    summary?: string;
    content?: string;
    /** Authored content size in bytes. The metric helper can also measure supplied text. */
    contentSize?: number;
    complexity?: number;
    metrics?: Readonly<Record<string, number>>;
}

interface GraphOptions<N extends GraphNode = GraphNode, E extends GraphLink = GraphLink> extends GraphData<N, E> {
    /** Rendering extension supplied by loom-core/wires. */
    wireProgram?: WireProgram;
    /** Composite marks over a host background, for example an SVG group boundary layer. Set on the canvas's first mount. */
    transparentBackground?: boolean;
    mode?: Mode;
    theme?: Theme<NoInfer<N>, NoInfer<E>>;
    layout?: LayoutOptions<NoInfer<N>>;
    art?: {
        urlFor: (node: NoInfer<N>) => string | undefined;
    };
    sim?: 'main' | 'worker';
    workerURL?: string | URL;
    reducedMotion?: 'respect' | 'ignore';
}

interface GraphStats {
    firstSubmitMs: number;
    frames: number;
    simTicks: number;
    drawCalls: number;
    labels: number;
    imageTiles: number;
    /** Bytes in the packed position/radius and edge-endpoint arrays. */
    geometryBytes: number;
    dpr: number;
    pendingFrame: boolean;
    transport: 'main' | 'transfer' | 'shared';
}

interface GraphViewport {
    x: number;
    y: number;
    z: number;
    zoom: number;
    yaw: number;
    pitch: number;
}

interface LayoutOptions<N extends GraphNode = GraphNode> {
    /** 0 uses the active force mode. 1 places movable nodes exactly on their anchors. */
    blend?: number;
    laneOrder?: readonly string[];
    /** Classify nodes into lanes. The default uses node.kind. */
    laneBy?: (node: N, index: number) => string;
    laneGap?: number;
    /** Minimum world-space distance between successive orbit rings. */
    orbitGap?: number;
    /** Depth multiplier for generated Cloud coordinates. Authored z coordinates take precedence. */
    cloudDepth?: number;
    /** Slowly orbit an idle Cloud. Reduced motion suppresses automatic rotation. */
    autoRotate?: boolean;
    rowGap?: number;
    direction?: 'horizontal' | 'vertical';
    anchor?: ((node: N, index: number) => {
        x: number;
        y: number;
        z?: number;
    } | null | undefined) | null;
    repulsion?: number;
    linkDistance?: number;
    springStrength?: number;
    /** Per-kind rest distances and multipliers for the global spring strength. */
    springsByKind?: Readonly<Record<string, {
        distance?: number;
        strength?: number;
    }>>;
    pinOnDrag?: boolean;
    guides?: boolean;
}

interface LoomGraph<N extends GraphNode = GraphNode, E extends GraphLink = GraphLink> {
    /** Request one paint on the existing scheduler. Honors pause, visibility and disposal. */
    invalidate(): void;
    /** Subscribe to actual paints. The first subscription wakes an idle graph once. */
    onFrame(listener: (frame: GraphFrame) => void): () => void;
    /** Read current projected points synchronously, including while the graph is paused. */
    getFrame(): GraphFrame;
    /** Attach an optional timing probe to this graph. Returns its detach function. */
    onTiming(probe: FrameProbe): () => void;
    select(id: string | null): void;
    focus(id: string): void;
    setMode(mode: Mode): void;
    setLayout(options: LayoutOptions<N>): void;
    setTheme(theme: Theme<N, E>): void;
    /** Convert canvas CSS pixels to the camera-facing world plane at the given camera depth. */
    screenToWorld(x: number, y: number, depth?: number): {
        x: number;
        y: number;
        z: number;
    };
    getViewport(): GraphViewport;
    setViewport(viewport: GraphViewport): void;
    getPosition(id: string): {
        x: number;
        y: number;
        z: number;
        pinned: boolean;
    };
    pin(id: string, position?: {
        x: number;
        y: number;
        z?: number;
    }): void;
    unpin(id: string): void;
    /** Frame the graph bounds. Pass true to apply the fitted viewport synchronously. */
    fit(immediate?: boolean): void;
    reset(): void;
    pause(): void;
    resume(): void;
    resize(): void;
    destroy(): void;
    on<K extends keyof GraphEvents>(type: K, listener: (value: GraphEvents[K]) => void): () => void;
    stats(): GraphStats;
}

interface NodeStyle {
    shape?: NodeShape;
    color?: string;
    /** Absolute world-space radius. Omit to retain degree-based sizing. */
    radius?: number;
}

interface Theme<N extends GraphNode = GraphNode, E extends GraphLink = GraphLink> {
    kind: Readonly<Record<string, string>>;
    ink: string;
    dim: string;
    accent: string;
    bg: string;
    bezel: string;
    font: string;
    fontSize: number;
    radii: {
        hub: number;
        content: number;
    };
    plateAlpha: number;
    nodes?: {
        scale?: number;
        artwork?: boolean;
        ringWidth?: number;
        fill?: number;
        byKind?: Readonly<Record<string, NodeStyle>>;
        resolve?: (node: N, degree: number) => NodeStyle | undefined;
    };
    wires?: WireStyle & {
        routing?: WireRoute;
        hotWidth?: number;
        byKind?: Readonly<Record<string, WireStyle>>;
        resolve?: (link: E, index: number) => WireStyle | undefined;
    };
    grid?: {
        spacing?: number;
        color?: string;
        opacity?: number;
    };
    labels?: {
        density?: number;
        visibility?: 'auto' | 'focus' | 'none';
        alternateSide?: boolean;
    };
}

interface WireStyle {
    color?: string;
    opacity?: number;
    width?: number;
    pattern?: WirePattern;
}

interface EditorChange {
    op: EditorOperation['op'];
    id: string;
}

interface EditorCheckpoint {
    readonly version: 1;
    readonly documentId: string;
    readonly revision: number;
    readonly data: EditorData;
}

interface EditorData extends GraphData<EditorNode, EditorLink> {
    readonly nodes: readonly EditorNode[];
    readonly links: readonly EditorLink[];
    readonly [field: string]: unknown;
}

type EditorLink = Readonly<GraphLink & {
    id: string;
} & Record<string, unknown>>;

type EditorOperation = {
    op: 'node.add';
    value: GraphNode | EditorNode;
} | {
    op: 'link.add';
    value: (GraphLink & {
        id: string;
    }) | EditorLink;
} | ({
    op: 'node.update';
    id: string;
} & Patch<GraphNode>) | ({
    op: 'link.update';
    id: string;
} & Patch<GraphLink>) | {
    op: 'node.remove';
    id: string;
    cascade?: boolean;
} | {
    op: 'link.remove';
    id: string;
};

interface EditorQuery {
    entity: 'node' | 'link';
    text?: string;
    kind?: string;
    incidentTo?: string;
    offset?: number;
    limit?: number;
}

type EditorReceipt = {
    ok: true;
    revision: number;
    changes: readonly EditorChange[];
} | {
    ok: false;
    revision: number;
    error: {
        code: EditorErrorCode;
        path: string;
        message: string;
    };
};

interface EditorSnapshot extends EditorCheckpoint {
    readonly canUndo: boolean;
    readonly canRedo: boolean;
}

interface EditorTransaction {
    version: 1;
    documentId?: string;
    expectedRevision?: number;
    operations: readonly EditorOperation[];
}

interface DrawingStyle {
    fill: 'solid' | 'hachure' | 'cross-hatch';
    /** Zero uses exact geometry. Higher values perturb outlines and wire handles. */
    roughness: number;
    /** Perpendicular distance between hatch lines, in CSS pixels. */
    hatchSpacing: number;
}

interface WireEffects {
    /** Centre-to-centre separation of parallel paths at their midpoint, in CSS pixels. */
    separation: number;
    direction: 'none' | 'arrow' | 'flow';
    scope: 'selected' | 'all';
    /** Distance the pulse travels in CSS pixels per second. */
    speed: number;
}

interface WireGraph<N extends GraphNode = GraphNode, E extends GraphLink = GraphLink> extends LoomGraph<N, E> {
    getWireEffects(): Readonly<WireEffects>;
    setWireEffects(patch: Partial<WireEffects>): void;
    getDrawingStyle(): Readonly<DrawingStyle>;
    setDrawingStyle(patch: Partial<DrawingStyle>): void;
}

interface DrilldownGroup {
    taxonomy: string;
    id: string;
    label?: string;
    /** Stable node IDs, including all overlapping memberships. */
    members: readonly string[];
}

type DrilldownLevel = {
    kind: 'overview';
    label: string;
} | {
    kind: 'node';
    id: string;
    label: string;
    hops: number;
    direction: LinkDirection;
    fromOverview?: true;
} | {
    kind: 'group';
    taxonomy: string;
    id: string;
    label: string;
    memberCount: number;
    action: GroupView;
};

interface DrilldownOptions<N extends GraphNode = GraphNode, E extends GraphLink = GraphLink> {
    selectAction?: NodeAction | ((node: N) => NodeAction);
    openAction?: NodeAction | ((node: N) => NodeAction);
    groupAction?: GroupAction | ((group: DrilldownGroup) => GroupAction);
    groupFor?: (node: N) => DrilldownGroup | undefined;
    neighborhood?: Neighborhood<E>;
    /** The default isolated detail uses free Drift. An empty object inherits the overview settings. */
    detail?: {
        mode?: Mode;
        layout?: LayoutOptions<N>;
    };
    /** Ring spacing or radial expansion multiplier. Defaults to 2. */
    spread?: number;
    arrangement?: 'rings' | 'radial';
    /** World-space spacing for ring targets or coincident radial members. */
    memberSpacing?: number;
    /** Force-to-anchor blend during in-place expansion. Defaults to 0.7. */
    expansionBlend?: number;
}

interface DrilldownSnapshot<N extends GraphNode, E extends GraphLink> {
    /** Directly mountable, in source order. Only a scope change replaces this object. */
    readonly data: GraphData<N, E>;
    readonly path: readonly DrilldownLevel[];
    /** All members of the current group in parent source order, empty at other levels. */
    readonly groupMembers: readonly N[];
    readonly selected: string | null;
    readonly options: Readonly<DrilldownOptions<N, E>>;
}

interface Neighborhood<E extends GraphLink = GraphLink> {
    hops?: number;
    direction?: LinkDirection;
    includeLink?: (link: E) => boolean;
}

interface BoundaryNode<N> {
    node: N;
    /** Counts relative to the supplied group. */
    incoming: number;
    outgoing: number;
}

interface Neighbor<N, E> {
    node: N;
    /** Parallel links in source order. */
    links: readonly E[];
}

interface SearchOptions {
    /** Restrict results to a drilldown or group without rebuilding the index. */
    within?: ReadonlySet<string>;
    limit?: number;
}

interface AtlasBlock {
    topic: number;
    articles: [id: number, title: string, degree: number][];
    edges: [source: number, target: number][];
}

interface AtlasCrossing {
    source: number;
    target: number;
    sourceTitle: string;
    targetTitle: string;
    sourceTopic: number;
    targetTopic: number;
}

interface AtlasLink extends GraphLink {
    sourceTopic: number;
    targetTopic: number;
}

interface AtlasManifest {
    topics: readonly AtlasTopic[];
    /** [source topic, target topic, hyperlink count], including links within a topic. */
    connections: readonly (readonly number[])[];
}

interface AtlasNode extends GraphNode {
    topic: number;
    article?: number;
}

interface AtlasReader {
    read(topics: readonly number[]): Promise<AtlasBlock[]>;
    stats(): AtlasReads;
    close(): void;
}

interface AtlasReads {
    bytes: number;
    requests: number;
}

interface AtlasSnapshot {
    mode: AtlasLoading;
    layout: AtlasLayout;
    expanded: readonly number[];
    loaded: readonly number[];
    pending: readonly number[];
    reads: AtlasReads;
    scene: AtlasScene;
    error: string | null;
}

interface AtlasTopic {
    id: number;
    label: string;
    color: string;
    first: number;
    count: number;
    x: number;
    y: number;
}

interface AtlasMapOptions {
    theme: Theme<AtlasNode, AtlasLink>;
    keepView?: boolean;
    /** Ease visible nodes and the camera between layouts. Defaults to false. */
    animateLayouts?: boolean;
    /** Playback rate for layout changes. 1 takes 700 ms. Can be adjusted mid-transition. */
    layoutSpeed?: number;
    /** The node the camera follows across layouts, or null when manual navigation takes over. */
    onFollowChange?: (id: string | null) => void;
    /** Translate article positions with their topic, including articles that load later. Defaults to true. */
    moveMembers?: boolean;
    /** How carried articles approach their new positions. Defaults to rigid. Springs respect reduced motion. */
    memberMotion?: AtlasMemberMotion;
    /** Strength and damping for carried articles. Both default to 1. */
    spring?: Partial<AtlasSpringSettings>;
    positions?: AtlasPositions;
    onPositionsChange?: (positions: AtlasPositions) => void;
    onPick?: (node: AtlasNode) => void;
    /** Override double-click, double-tap or Enter. By default a topic opens and the camera focuses the node. */
    onOpen?: (node: AtlasNode) => void;
    /** A background click after node hit testing, with its current projected scene. */
    onBackgroundClick?: (point: GraphEvents['backgroundclick'], frame: GraphFrame, scene: AtlasScene) => void;
    onFrame?: (frame: GraphFrame, scene: AtlasScene) => void;
}

interface AtlasPositions {
    topics: Record<string, Point>;
    members: Record<string, Point>;
    articles: Record<string, Point>;
}

interface AtlasSpringSettings {
    /** Stiffness relative to the original atlas spring. Lower values produce a longer trail. */
    strength: number;
    /** Damping ratio. At 1, a resting article catches up without overshooting a fixed target. */
    damping: number;
}

interface WikipediaImage {
    title: string;
    src: string;
    width: number;
    height: number;
    fileUrl: string;
}

interface AtlasSQLiteOptions {
    database: string | URL;
    /** Uncompressed database size. Supply this when the host may compress HEAD responses. */
    databaseBytes?: number;
    worker: string | URL;
    wasm: string | URL;
    pageSize: number;
}

interface CardOptions<N extends GraphNode, E extends GraphLink> {
    root?: string;
    appearance?: 'cards' | 'dots';
    showLabels?: boolean;
    showPorts?: boolean;
    showArrows?: boolean;
    /** Center a card on double-click, double-tap or Enter. Defaults to true. */
    focusOnOpen?: boolean;
    /** Use authored coordinates if supplied. Set false to arrange a neighborhood around its root. */
    useNodePositions?: boolean;
    image?: (node: N) => string | undefined;
    badge?: (node: N) => string;
    tint?: (node: N) => string;
    relationship?: (edge: E) => string;
    onSelect?: (node: N) => void;
}

interface ClusterGroup {
    readonly id: string;
    readonly center: Readonly<ClusterPoint>;
    readonly radius: number;
    readonly members: readonly string[];
}

interface ClusterOptions {
    /** World units between neighbouring group envelopes. */
    gap?: number;
    /** Controls density within each group, in world units. */
    spacing?: number;
    /** Preferred width divided by height when packing rows. */
    aspectRatio?: number;
    dimensions?: 2 | 3;
    depth?: number;
}

interface ClusterPoint {
    x: number;
    y: number;
    z: number;
}

interface ScaleOptions {
    domain?: readonly [number, number];
    range?: readonly [number, number];
    curve?: 'linear' | 'sqrt' | 'log';
}

interface PerformanceSample extends GraphStats {
    idle: boolean;
    /** Graph draw submissions per second over the last second. */
    fps: number;
    /** Mean main-thread time in a Loom scheduler callback over the last second. */
    mainThreadMs: number | null;
    p95FrameMs: number | null;
    frameIntervals: readonly number[];
    /** Most recent asynchronous GPU draw sample, in milliseconds. */
    gpuMs: number | null;
    gpuStatus: GPUStatus;
    /** Browser-reported JavaScript heap usage, in bytes, when available. */
    heapBytes: number | null;
}

interface AnnotationOptions {
    /** Taxonomy id to all its groups, or an explicit list of term ids. */
    bubbles?: Readonly<Record<string, true | readonly string[]>>;
    /** Hide every boundary and its canvas hit area while retaining per-taxonomy choices. Defaults to true. */
    bubblesVisible?: boolean;
    /** Label visible group boundaries at their upper edge. Labels can open the group. */
    bubbleLabels?: boolean;
    padding?: number;
    laneTaxonomy?: string;
    tooltips?: boolean;
    colorFor?: (group: TaxonGroup) => string;
    boundary?: BoundaryStyle;
    boundaryFor?: (group: TaxonGroup) => BoundaryStyle | undefined;
    /** An optional sibling behind a transparent graph canvas, in the same coordinate space. */
    underlay?: HTMLElement;
    activeGroup?: {
        taxonomy: string;
        id: string;
        boundary?: 'outline' | 'fade' | 'hide' | 'keep';
        shape?: BoundaryStyle['shape'];
    };
    /** Defaults to double-click. Controls keeps the canvas available for graph gestures. */
    groupGesture?: 'click' | 'double-click' | 'controls';
    /** Called by a lane button or the configured gesture in a visible bubble, after node picking. */
    onOpenGroup?: (group: TaxonGroup) => void;
}

interface BoundaryStyle {
    shape?: 'hull' | 'cloud';
    /** Screen-space padding around each projected node radius. */
    padding?: number;
    color?: string;
    fillOpacity?: number;
    strokeOpacity?: number;
    width?: number;
    pattern?: WirePattern;
}

interface GraphAnnotations {
    setOptions(options: Partial<AnnotationOptions>): void;
    setIndex(index: TaxonomyIndex): void;
    destroy(): void;
}

interface GraphLanguage<N extends GraphNode = GraphNode> {
    title?: (node: N) => string;
    connections?: (count: number) => string;
    tooltip?: (node: N, description: NodeDescription) => TooltipContent;
    ungrouped?: string;
}

interface NodeDescription {
    title: string;
    connections: string;
    groups: readonly TaxonGroup[];
}

interface RelationGrouping {
    relation: string;
    groupEnd: 'source' | 'target';
}

interface TaxonGroup extends TaxonTerm {
    readonly taxonomy: string;
    readonly id: string;
    readonly key: string;
    readonly color: string;
    /** Indices in the original graph's nodes array. */
    readonly members: readonly number[];
}

interface TaxonTerm {
    label: string;
    color?: string;
    shape?: NodeShape;
    description?: string;
}

interface TaxonomyConfig<N extends GraphNode = GraphNode, E extends GraphLink = GraphLink> {
    taxonomies: readonly TaxonomyDefinition<N, E>[];
    language?: GraphLanguage<N>;
}

interface TaxonomyContext<N extends GraphNode, E extends GraphLink> {
    nodes: ReadonlyMap<string, N>;
    linksFor(id: string): readonly E[];
}

interface TaxonomyDefinition<N extends GraphNode = GraphNode, E extends GraphLink = GraphLink> {
    id: string;
    label: string;
    by: MembershipField<N> | RelationGrouping | ((node: N, context: TaxonomyContext<N, E>) => Membership);
    /** When provided, only the listed input values contribute memberships. */
    remap?: Readonly<Record<string, string | readonly string[]>>;
    terms?: Readonly<Record<string, TaxonTerm>>;
}

interface TaxonomyIndex {
    readonly groups: readonly TaxonGroup[];
    readonly ungrouped: string;
    legend(taxonomy: string): readonly TaxonGroup[];
    describe(id: string): NodeDescription | undefined;
    /** First membership, shared by exclusive lane placement and marker styling. */
    primary(id: string, taxonomy: string): TaxonGroup | undefined;
    tooltip(id: string): TooltipContent | undefined;
    /** Multi-membership nodes use their first membership for exclusive lane placement. */
    laneBy(taxonomy: string): (node: GraphNode) => string;
    nodeIndex(id: string): number | undefined;
}

interface TooltipContent {
    title: string;
    lines: readonly string[];
}
